-- Development fixture only. Never run automatically or on production.
-- Required invocation: psql -X -1 -v ON_ERROR_STOP=1 -f db/seeds/mock_data.sql
-- All data is fictional. Password: KicauMock2026! (Argon2id, application parameters).
-- ON COMMIT DROP intentionally requires the explicit transaction above.
DO $schema$
BEGIN
 IF EXISTS(SELECT FROM unnest(ARRAY['cloud_read.v_users','cloud_read.v_user_auth_providers',
 'cloud_read.v_participant_assessments','cloud_read.mv_round_score_summary','cloud_read.mv_arena_dashboard',
 'cloud_read.refresh_status','iam.account_tokens','judging.score_operations']) x(name) WHERE to_regclass(name) IS NULL)
 OR NOT EXISTS(SELECT FROM information_schema.columns WHERE table_schema='cloud_read' AND table_name='v_users' AND column_name='has_password')
 OR (SELECT count(*) FROM iam.roles WHERE name IN ('superadmin','admin_arena','operator','juri','peserta','penjoki'))<>6 THEN
  RAISE EXCEPTION 'Apply migrations 001..007 before this development fixture';
 END IF;
END;
$schema$;

-- Preflight identity checks precede all application table mutations.
CREATE TEMP TABLE _kicau_mock_expected(entity text NOT NULL, id uuid NOT NULL, identity jsonb NOT NULL, payload jsonb NOT NULL) ON COMMIT DROP;

DO $identities$
DECLARE fixture record; actual jsonb; role_id uuid;
BEGIN
 FOR fixture IN SELECT * FROM _kicau_mock_expected LOOP
  EXECUTE format('SELECT to_jsonb(t) FROM %s t WHERE id=$1',fixture.entity::regclass) INTO actual USING fixture.id;
  IF actual IS NOT NULL AND NOT (actual @> fixture.identity) THEN
   RAISE EXCEPTION 'Mock identity collision in % at ID %; no fixture changes applied',fixture.entity,fixture.id;
  END IF;
  IF fixture.payload ? '_role' THEN
   SELECT id INTO STRICT role_id FROM iam.roles WHERE name=fixture.payload->>'_role';
   IF actual IS NOT NULL AND actual->>'role_id'<>role_id::text THEN
    RAISE EXCEPTION 'Mock role identity collision in %',fixture.entity;
   END IF;
  END IF;
 END LOOP;
END;
$identities$;

-- Inserts follow FK dependency order. Existing rows are never updated.
-- Missing natural keys with another ID abort the caller transaction via UNIQUE constraints.
DO $insert$
DECLARE fixture record; columns_sql text; payload jsonb; role_id uuid;
BEGIN
 FOR fixture IN SELECT * FROM _kicau_mock_expected ORDER BY
  CASE entity WHEN 'iam.users' THEN 1 WHEN 'asset.arenas' THEN 2
  WHEN 'asset.gantangan' THEN 3 WHEN 'competition.events' THEN 4
  WHEN 'competition.categories' THEN 5 WHEN 'judging.score_criteria' THEN 6
  WHEN 'competition.rounds' THEN 7 WHEN 'asset.owners' THEN 8 WHEN 'asset.birds' THEN 9 ELSE 10 END,id
 LOOP
  payload:=fixture.payload;
  IF payload ? '_role' THEN
   SELECT id INTO STRICT role_id FROM iam.roles WHERE name=payload->>'_role';
   payload:=(payload-'_role')||jsonb_build_object('role_id',role_id);
  END IF;
  SELECT string_agg(format('%I',key),',' ORDER BY key) INTO columns_sql FROM jsonb_object_keys(payload) key;
  EXECUTE format('INSERT INTO %s(%s) SELECT %s FROM jsonb_populate_record(NULL::%s,$1) ON CONFLICT(id) DO NOTHING',
   fixture.entity::regclass,columns_sql,columns_sql,fixture.entity::regclass) USING payload;
 END LOOP;
END;
$insert$;

-- A manual development seed also updates administrative snapshots, not live scoring state.
SELECT pg_advisory_xact_lock(753120);
REFRESH MATERIALIZED VIEW cloud_read.mv_round_score_summary;
UPDATE cloud_read.refresh_status SET snapshot_at=CURRENT_TIMESTAMP,refreshed_at=clock_timestamp() WHERE view_name='mv_round_score_summary';
SELECT pg_advisory_xact_lock(753121);
REFRESH MATERIALIZED VIEW cloud_read.mv_arena_dashboard;
UPDATE cloud_read.refresh_status SET snapshot_at=CURRENT_TIMESTAMP,refreshed_at=clock_timestamp() WHERE view_name='mv_arena_dashboard';
